import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"Integrations & Hooks","description":"","frontmatter":{"title":"Integrations & Hooks"},"headers":[],"relativePath":"en/reference/integrations.md","filePath":"en/reference/integrations.md","lastUpdated":1786545590000}'),r={name:"en/reference/integrations.md"};function i(l,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="integrations-hooks" tabindex="-1">Integrations &amp; Hooks <a class="header-anchor" href="#integrations-hooks" aria-label="Permalink to &quot;Integrations &amp; Hooks&quot;">​</a></h1><p>JoyMart integrates with several popular Spigot/Paper plugins. All integrations are optional — JoyMart detects them automatically at startup.</p><h2 id="placeholderapi" tabindex="-1">PlaceholderAPI <a class="header-anchor" href="#placeholderapi" aria-label="Permalink to &quot;PlaceholderAPI&quot;">​</a></h2><p>Once PlaceholderAPI is installed, JoyMart registers the following placeholders:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th></tr></thead><tbody><tr><td><code>%gamebox_tokens%</code></td><td>Current player&#39;s token balance</td></tr><tr><td><code>%gamebox_highscore_&lt;id&gt;%</code></td><td>Current player&#39;s high score in a game (e.g. <code>%gamebox_highscore_2048%</code>)</td></tr><tr><td><code>%gamebox_ingame%</code></td><td>Whether the current player is in a game (true/false)</td></tr></tbody></table><p>The implementation is in <code>GameBoxPlaceholders.java</code>. Placeholders are registered automatically when PlaceholderAPI is detected.</p><h2 id="vault-economy" tabindex="-1">Vault Economy <a class="header-anchor" href="#vault-economy" aria-label="Permalink to &quot;Vault Economy&quot;">​</a></h2><p>When Vault is present and <code>economy.vault: true</code> in config.yml:</p><ul><li>Games can award money (coins) alongside tokens</li><li>The token shop can charge coins</li><li>Lottery / SlotMachine prize pools can include money rewards</li><li>All money operations go through Vault&#39;s Economy API</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Without Vault, only the internal JoyMart token system is used.</p></div><h2 id="calendarevents" tabindex="-1">CalendarEvents <a class="header-anchor" href="#calendarevents" aria-label="Permalink to &quot;CalendarEvents&quot;">​</a></h2><p>JoyMart hooks into CalendarEvents for seasonal easter eggs. When CalendarEvents is detected:</p><ul><li>Special themed game icons or messages may appear during holidays</li><li>The hook is in <code>CalendarEventsHook.java</code> and is auto-detected — no configuration needed</li></ul><h2 id="bstats" tabindex="-1">bStats <a class="header-anchor" href="#bstats" aria-label="Permalink to &quot;bStats&quot;">​</a></h2><p>JoyMart uses bStats for anonymous usage statistics:</p><ul><li>Enabled by default (can be disabled with <code>bstats: false</code> in config.yml)</li><li>Reports: server version, plugin version, game usage, storage type</li><li>Data is sent to <a href="https://bstats.org/" target="_blank" rel="noreferrer">bStats.org</a> and is fully anonymous</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>bStats only collects aggregated, anonymized metric data — it never includes any personal player information or sensitive server configuration.</p></div><h2 id="soft-dependencies-summary" tabindex="-1">Soft Dependencies Summary <a class="header-anchor" href="#soft-dependencies-summary" aria-label="Permalink to &quot;Soft Dependencies Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plugin</th><th>Required?</th><th>Purpose</th></tr></thead><tbody><tr><td>Vault</td><td>Optional</td><td>Economy hook (coins)</td></tr><tr><td>PlaceholderAPI</td><td>Optional</td><td>Placeholder variables</td></tr><tr><td>CalendarEvents</td><td>Optional</td><td>Seasonal easter eggs</td></tr><tr><td>bStats</td><td>Built-in</td><td>Anonymous metrics</td></tr></tbody></table><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./../guides/configuration">Configuration</a></li><li><a href="./scoring">Scoring &amp; Events</a></li><li><a href="./api">Public API</a></li></ul>',21)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
